// Helper function to safely construct a full URL from a base and a path
const getFullApiUrl = (base, path) => {
  if (!base || !path) {
    return null;
  }
  const cleanBase = base.endsWith('/') ? base.slice(0, -1) : base;
  const cleanPath = path.startsWith('/') ? path : `/${path}`;
  return cleanBase + cleanPath;
};

// Get the single base URL from the environment
const apiBaseUrlFromEnv = this.$env.getProperty("apiBaseUrl");

// Central validation for the base URL
if (!apiBaseUrlFromEnv || apiBaseUrlFromEnv.trim() === "") {
  console.warn("The 'apiBaseUrl' environment variable is not set. API URLs cannot be configured.");
} else {
  // Array of API endpoint configurations
  const apiEndpoints = [
    {
      path: "/api/lonti_app_crm/1.0",
      urlProperty: 'apiBaseUrl',
      service: this.lontiAppCrmApi,
      serviceName: 'lontiAppCrmApi'
    },
    {
      path: "/api/lonti_util_saas_app_authorization/1.0",
      urlProperty: 'authApiBaseUrl',
      service: this.lontiUtilSaasAppAuthorizationApi, // Assumed to exist
      serviceName: 'lontiUtilSaasAppAuthorizationApi'
    }
  ];

  // Iterate over each configuration to set the URL and configure the service
  apiEndpoints.forEach(endpoint => {
    const fullApiUrl = getFullApiUrl(apiBaseUrlFromEnv, endpoint.path);
    this[endpoint.urlProperty] = fullApiUrl;

    if (endpoint.service && typeof endpoint.service.setServerUrl === 'function') {
      endpoint.service.setServerUrl(fullApiUrl);
    } else {
      console.warn(`The '${endpoint.serviceName}' service or its 'setServerUrl' method is not available.`);
    }
  });
}

// --- 1. Setup & Configuration ---
const {
    page,
    limit = 25,
    query,
    apiType = 'crm',
    customEntityKey
} = options;

// Select the appropriate base URL based on apiType
const baseUrl = apiType === 'auth' ? this.authApiBaseUrl : this.apiBaseUrl;

if (!baseUrl) {
    const errorMessage = `The base URL for the '${apiType}' API is not configured.`;
    console.error(errorMessage);
    this.utilityService.toast(errorMessage, "ERROR");
    throw new Error(errorMessage);
}

// --- 2. URL Construction ---
let url = new URL(`${baseUrl}/${entity}`);
const params = url.searchParams;

// 1. Handle the 'eventlog' outlier first
if (entity === "eventlog") {
    params.set('page', 0);
    params.set('pageSize', limit);
}
// 2. Apply standard pagination if a page is provided
// We remove the "/" and "attachment" checks because sub-resources 
// (like attachment/Contact/1) usually support limit/offset too.
else if (page !== undefined && page !== null) {
    const offset = (page - 1) * limit;

    params.set('limit', limit);
    params.set('offset', offset);
}

// Append query parameters from the options object
if (query) {
    const tempSearchParams = new URLSearchParams(query);

    // --- 1. Handle the special 'pipelineId_eq' case first ---
    // Check if the specific pipeline ID parameter exists.
    if (tempSearchParams.has('pipelineId_eq') && entity !== "pipeline") {
        const pipelineId = tempSearchParams.get('pipelineId_eq');

        // If a value exists, append it to the URL's path.
        if (pipelineId) {
            url.pathname += `/pipeline/${pipelineId}`;
        }

        // IMPORTANT: Delete the parameter so it isn't added as a regular search param later.
        tempSearchParams.delete('pipelineId_eq');
    }

    // --- 2. Iterate over the REMAINING parameters ---
    tempSearchParams.forEach((value, key) => {
        if (key.endsWith('_in') || key.endsWith('_notin')) {
            // This part remains the same to handle your list parameters.
            let currentUrlString = url.toString();
            currentUrlString += currentUrlString.includes('?') ? '&' : '?';
            currentUrlString += `${encodeURIComponent(key)}=${value}`;
            url = new URL(currentUrlString);
        } else {
            // All other parameters are appended normally.
            url.searchParams.append(key, value);
        }
    });
}

// --- 3. API Request & Response Handling ---
try {
    const headers = this.authService.getHeaders();
    const response = await fetch(url.toString(), {
        method: 'GET',
        headers: headers
    });

    if (!response.ok) {
        let errorData;
        try {
            errorData = await response.json();
        } catch (e) {
            errorData = await response.text();
        }
        const errorMessage = errorData?.message || (typeof errorData === 'string' ? errorData : `HTTP error! status: ${response.status}`);
        throw new Error(errorMessage);


    }

    // NOTE: this.$timeout is a legacy AngularJS feature for triggering a digest cycle.
    // It is generally not needed in modern JavaScript frameworks and can likely be removed.
    this.$timeout(100);

    if (response.status === 204) {
        return response;
    }

    const res = await response.json();

    const entityKey = customEntityKey ?? entity.split("/")[0];

    // Get the array of entities, handling different possible response shapes.
    const entities = res?.[entityKey] ?? res ?? [];

    // Get the total and totalFiltered counts, providing a default if they don't exist.
    const total = res?.metadata?.totalCount ?? 0;
    const totalFiltered = res?.metadata?.totalFiltered ?? entities.length; // Default to the returned count if not provided
    const pageCount = res?.metadata?.pageCount ?? 1;
    const hasNextPage = res?.metadata?.hasNextPage ?? false;

    // Return a single object containing all the data.
    if (Array.isArray(entities)) {
        return {
            entities,
            total,
            totalFiltered,
            pageCount,
            hasNextPage
        };
    } else {
        return res;
    }

} catch (error) {
    const errorMessage = error?.message || "An unexpected API error occurred.";
    console.error(`API Error in getData for entity '${entity}':`, error);
    this.utilityService.toast(errorMessage, "ERROR");
    throw error; // Re-throw the error for the calling function to handle
}

