    // Construct the full function name (e.g., "lonti_app_crm_service_contact_Insert")
    const apiFunction = `${functionPrefix}${entityAction}`;

    if (typeof selectedApi.service[apiFunction] !== 'function') {
        const errorMessage = `The function '${apiFunction}' does not exist on the '${apiType}' service.`;
        console.error(errorMessage);
        throw new Error(errorMessage);
    }

    const apiHeaders = { headers: this.authService.getHeaders() };

    // Dynamically call the correct function on the selected API service
    let response;
    if (apiType === "auth" || type === "tenant") {
        response = await selectedApi.service[apiFunction](requestBody, apiHeaders);
    } else {
        response = await selectedApi.service[apiFunction](parameters, requestBody, apiHeaders);
